import { permissionSchema, rolePermissions } from '@inventory/contracts';
import type { Permission, AccessRole } from '@inventory/contracts';
const areas: Record<string, string> = {
  business: 'Business settings',
  locations: 'Stores and warehouses',
  products: 'Products and pricing',
  stock: 'Inventory and transfers',
  sales: 'Sales and receipts',
  purchases: 'Purchasing',
  customers: 'Customers and credit',
  payments: 'Payments',
  reports: 'Reports',
  users: 'Team',
  audit: 'Audit history',
  onlineStore: 'Online store',
};
const actions: Record<string, string> = {
  read: 'View',
  view: 'View',
  manage: 'Manage',
  write: 'Create and edit',
  refund: 'Issue refunds',
  void: 'Void sales',
  credit: 'Manage credit limits',
  override: 'Override credit controls',
  cash: 'Operate cash shifts',
};
export function permissionLabel(permission: Permission) {
  const [area = '', action = ''] = permission.split('.');
  return `${actions[action] ?? action} · ${areas[area] ?? area}`;
}
/** Presentation of existing assignable grants, not backend authorization. */
export function permissionGroups(storeScoped: boolean) {
  const allowed = permissionSchema.options.filter(
    (p) =>
      p !== 'users.write' &&
      (!storeScoped || !['users.read', 'business.write', 'onlineStore.manage'].includes(p)),
  );
  return Object.entries(areas)
    .map(([key, label]) => ({
      key,
      label,
      permissions: allowed.filter((p) => p.startsWith(`${key}.`)),
    }))
    .filter((group) => group.permissions.length);
}
export const roleGuidance: Record<string, string> = {
  owner:
    'Full business administration, including people and access. Owners cannot be limited to one store.',
  manager:
    'Operational management within the selected business, store or warehouse; no role delegation.',
  cashier: 'Checkout, customer records and payment records within the selected scope.',
  viewer: 'Read-only access to business information and locations within the selected scope.',
  custom:
    'Choose only the capabilities this person needs. Sensitive financial actions are separate grants.',
};
export function roleCapabilities(role: AccessRole) {
  return rolePermissions(role).map(permissionLabel);
}

import { expect, it } from 'vitest';
import { permissionGroups, permissionLabel, roleCapabilities } from './access-presentation.js';
import { rolePermissions } from '@inventory/contracts';
it('groups only currently assignable permissions and preserves scope exclusions', () => {
  const business = permissionGroups(false).flatMap((group) => group.permissions);
  const scoped = permissionGroups(true).flatMap((group) => group.permissions);
  expect(new Set(business).size).toBe(business.length);
  expect(business).not.toContain('users.write');
  expect(business).toContain('business.write');
  expect(scoped).not.toContain('business.write');
  expect(scoped).not.toContain('users.read');
  expect(scoped).toContain('sales.refund');
  expect(business).toContain('onlineStore.view');
  expect(business).toContain('onlineStore.manage');
  expect(scoped).toContain('onlineStore.view');
  expect(scoped).not.toContain('onlineStore.manage');
});
it('describes roles using the canonical permissions without inventing grants', () => {
  for (const role of ['owner', 'manager', 'cashier', 'viewer'] as const)
    expect(roleCapabilities(role)).toEqual(rolePermissions(role).map(permissionLabel));
  expect(roleCapabilities('viewer')).toHaveLength(2);
  expect(permissionLabel('sales.refund')).toBe('Issue refunds · Sales and receipts');
});

