import { useState } from 'react';
import { hasPermission } from '@inventory/contracts';
import type { Membership, Workspace } from '@inventory/contracts';
import { RecordCollection } from '@/components/common/RecordCollection';
import { SearchControl } from '@/components/common/SearchControl';
import { FilterButton } from '@/components/common/FilterButton';
import { Popover, PopoverTrigger, PopoverContent } from '@/components/ui/Popover';
import { Select } from '@/components/ui/FormControls';
import { Button } from '@/components/ui/Button';
import { Plus } from 'lucide-react';
export function MemberCollection({
  workspace,
  busy,
  onAssign,
  onEdit,
}: {
  workspace: Workspace;
  busy: boolean;
  onAssign: () => void;
  onEdit: (member: Membership) => void;
}) {
  const [search, setSearch] = useState(''),
    [role, setRole] = useState(''),
    [status, setStatus] = useState('');
  const writable = hasPermission(workspace.business, 'users.write');
  const members = workspace.members.filter(
    (m) =>
      `${m.email} ${m.role}`.toLowerCase().includes(search.toLowerCase()) &&
      (!role || m.role === role) &&
      (!status || m.state === status),
  );
  const active = [role && `Role: ${role}`, status && `Status: ${status}`].filter(Boolean);
  return (
    <RecordCollection
      label="team members"
      columns={['Member', 'Role', 'Access scope']}
      onOpen={(id) => {
        const m = workspace.members.find((m) => m.accountId === id);
        if (m) onEdit(m);
      }}
      items={members.map((m) => ({
        id: m.accountId,
        title: m.email,
        subtitle: m.role,
        detail: m.scope?.storeId
          ? (workspace.locations.find((l) => l.id === m.scope?.storeId)?.name ?? 'Assigned store')
          : 'Business-wide',
        status: m.state,
        tone: m.state === 'active' ? 'success' : 'neutral',
      }))}
      actions={
        writable && (
          <Button disabled={busy} onClick={onAssign}>
            <Plus aria-hidden="true" />
            Assign member
          </Button>
        )
      }
      toolbar={
        <>
          <div className="collection-search">
            <SearchControl label="Search team members" value={search} onChange={setSearch} />
          </div>
          <Popover>
            <PopoverTrigger asChild>
              <FilterButton active={active} />
            </PopoverTrigger>
            <PopoverContent className="space-y-3">
              <label>
                Role
                <Select value={role} onChange={(e) => setRole(e.target.value)}>
                  <option value="">All roles</option>
                  {['owner', 'manager', 'cashier', 'viewer', 'custom'].map((r) => (
                    <option key={r}>{r}</option>
                  ))}
                </Select>
              </label>
              <label>
                Status
                <Select value={status} onChange={(e) => setStatus(e.target.value)}>
                  <option value="">All statuses</option>
                  {['active', 'suspended', 'archived'].map((r) => (
                    <option key={r}>{r}</option>
                  ))}
                </Select>
              </label>
            </PopoverContent>
          </Popover>
        </>
      }
    />
  );
}

import { ConfirmDialog } from '@/components/common/ConfirmDialog';
import { FormSheet } from '@/components/common/FormSheet';
import { MemberCollection } from './MemberCollection';
import { ScreenHeader } from '@/components/common/ScreenHeader';
import { hasPermission } from '@inventory/contracts';
import { AccessFields } from './AccessFields';
import { useState } from 'react';
import { assignMemberSchema, editMemberSchema } from '@inventory/contracts';
import type { Membership, Workspace } from '@inventory/contracts';
import type { OrganizationModel } from '@inventory/api-client';
import { Button } from '@/components/ui/Button';
import { Input, Select } from '@/components/ui/FormControls';
export function MemberEditor({
  model,
  workspace,
  busy,
}: {
  model: OrganizationModel;
  workspace: Workspace;
  busy: boolean;
}) {
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<Membership | null>(null);
  const [role, setRole] = useState('viewer');
  function edit(member: Membership | null) {
    setOpen(true);
    setEditing(member);
    setRole(member?.role ?? 'viewer');
  }
  const writable = hasPermission(workspace.business, 'users.write');
  return (
    <section aria-label="Business membership" className="screen-section">
      <ScreenHeader
        title="Membership"
        level={3}
        description={
          <>
            Assign an existing invited account. Owners control memberships; managers control
            locations; viewers can read locations.
          </>
        }
      />
      <MemberCollection
        workspace={workspace}
        busy={busy}
        onAssign={() => edit(null)}
        onEdit={edit}
      />
      {editing && (!writable || editing.state === 'archived') ? (
        <FormSheet title="Member details" open={open} onOpenChange={setOpen}>
          <p>{editing.email}</p>
          <p>Role: {editing.role}</p>
          <p>Status: {editing.state}</p>
          <p>
            Access:{' '}
            {workspace.locations.find((l) => l.id === editing.scope?.storeId)?.name ??
              'Business-wide'}
          </p>
          <p>Custom permissions: {editing.permissions?.join(', ') || 'Role defaults'}</p>
        </FormSheet>
      ) : (
        writable && (
          <FormSheet
            title={editing ? `Edit ${editing.email}` : 'Assign member'}
            open={open}
            onOpenChange={setOpen}
          >
            <form
              key={editing?.accountId ?? 'new'}
              className="screen-form"
              onSubmit={(event) => {
                event.preventDefault();
                const form = event.currentTarget;
                const data = new FormData(form);
                const access = {
                  scope: {
                    storeId: data.get('scopeStoreId') || null,
                    warehouseId: data.get('scopeWarehouseId') || null,
                  },
                  permissions: data.getAll('permission'),
                };
                void model.refresh(async () => {
                  if (editing)
                    await model.client.editMember(
                      workspace.business.id,
                      editing.accountId,
                      editMemberSchema.parse({
                        role: data.get('role'),
                        ...access,
                        state: data.get('state'),
                        version: editing.version,
                      }),
                    );
                  else
                    await model.client.assign(
                      workspace.business.id,
                      assignMemberSchema.parse({
                        email: data.get('email'),
                        role: data.get('role'),
                        ...access,
                      }),
                    );
                  setOpen(false);
                  form.reset();
                });
              }}
            >
              <fieldset disabled={busy} className="screen-form">
                <legend>{editing ? `Edit ${editing.email}` : 'Assign account'}</legend>
                {!editing && (
                  <>
                    <label htmlFor="member-email">Member email</label>
                    <Input id="member-email" name="email" type="email" required maxLength={254} />
                  </>
                )}
                <label htmlFor="member-role">Role</label>
                <Select
                  id="member-role"
                  name="role"
                  value={role}
                  onChange={(e) => setRole(e.target.value)}
                >
                  {['owner', 'manager', 'cashier', 'viewer', 'custom'].map((role) => (
                    <option key={role}>{role}</option>
                  ))}
                </Select>
                <AccessFields
                  key={editing?.accountId ?? 'new'}
                  role={role}
                  member={editing}
                  workspace={workspace}
                />
                {editing && (
                  <>
                    <label htmlFor="member-state">Membership state</label>
                    <Select id="member-state" name="state" defaultValue={editing.state}>
                      {['active', 'suspended', 'archived'].map((state) => (
                        <option key={state}>{state}</option>
                      ))}
                    </Select>
                    <p className="text-sm">
                      Keep at least one active owner. Archiving is permanent.
                    </p>
                  </>
                )}
                <div className="drawer-actions">
                  {' '}
                  <Button type="submit">{editing ? 'Save membership' : 'Assign member'}</Button>
                  {editing && (
                    <Button variant="outline" onClick={() => setOpen(false)}>
                      Cancel membership edit
                    </Button>
                  )}
                </div>
                {editing && (
                  <ConfirmDialog
                    title="Remove member access?"
                    trigger={
                      <Button variant="destructive" disabled={busy}>
                        Remove member access
                      </Button>
                    }
                    description="Permanently remove this membership. Other businesses and audit history remain intact. The last active owner cannot be removed."
                    confirmLabel="Remove access"
                    onConfirm={() => {
                      if (!editing || busy) return;
                      void model.refresh(async () => {
                        await model.client.editMember(
                          workspace.business.id,
                          editing.accountId,
                          editMemberSchema.parse({
                            role: editing.role,
                            state: 'archived',
                            version: editing.version,
                            scope: editing.scope,
                            permissions: editing.permissions,
                          }),
                        );
                        setOpen(false);
                      });
                    }}
                  />
                )}
              </fieldset>
            </form>
          </FormSheet>
        )
      )}
    </section>
  );
}

