  staff,
  locations,
  definition,
  salaryDefinition,
  run,
  onClose,
}: {
  staff: Staff;
  locations: Location[];
  definition: Definition;
  salaryDefinition?: Definition | undefined;
  run: (work: () => Promise<unknown>) => void;
  onClose: () => void;
}) {
  const [editing, setEditing] = useState(false);
  const { navigate } = useNavigation();
